select * from customer limit 5;

-- --Q1. What is the total revenue generated by male vs. female customers?
SELECT gender, SUM("purchase_amount_(usd)") AS revenue
FROM customer
GROUP BY gender;

--Q2. Which customers used a discount but still spent more than the average purchase amount?
SELECT customer_id, "purchase_amount_(usd)"
FROM customer
WHERE discount_applied = 'Yes' 
  AND "purchase_amount_(usd)" >= (SELECT AVG("purchase_amount_(usd)") FROM customer);

--Q3. Which are the top 5 products with the highest average review rating? 
select item_purchased, ROUND(AVG(review_rating)::numeric, 2) as "Average Product Rating"
from customer
group by item_purchased
order by avg(review_rating) desc
limit 5;
--Q4. Compare the average Purchase Amounts between Standard and Express Shipping.
SELECT 
    shipping_term_, 
    ROUND(AVG("purchase_amount_(usd)")::numeric, 2) AS avg_purchase_amount
FROM customer
WHERE shipping_term_ IN ('Standard', 'Express')
GROUP BY shipping_term_;
--Q5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers.
SELECT 
    "subscription_status",
    ROUND(AVG("purchase_amount_(usd)")::numeric, 2) AS avg_spend,
    SUM("purchase_amount_(usd)") AS total_revenue
FROM customer
GROUP BY "subscription_status";
--Q6. Which 5 products have the highest percentage of purchases with discounts applied? 
SELECT 
    item_purchased,
    ROUND(
        (COUNT(CASE WHEN discount_applied = 'Yes' THEN 1 END)::numeric / COUNT(*)) * 100, 
        2
    ) AS discount_percentage
FROM customer
GROUP BY item_purchased
ORDER BY discount_percentage DESC
LIMIT 5;
--Q7. Segment customers into New, Returning, and Loyal based on their total number of previous purchases, and show the count of each segment.
SELECT 
    customer_segment,
    COUNT(*) AS total_customers
FROM (
    SELECT 
        customer_id,
        CASE 
            WHEN previous_purchases = 1 THEN 'New'
            WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
            ELSE 'Loyal'
        END AS customer_segment
    FROM customer
) AS segmented_data
GROUP BY customer_segment
ORDER BY total_customers DESC;
--Q8. What are the top 3 most purchased products within each category?
WITH product_ranks AS (
    SELECT 
        category,
        item_purchased,
        COUNT(*) AS total_orders,
        DENSE_RANK() OVER (
            PARTITION BY category 
            ORDER BY COUNT(*) DESC
        ) AS item_rank
    FROM customer
    GROUP BY category, item_purchased
)
SELECT 
    category,
    item_purchased,
    total_orders,
    item_rank
FROM product_ranks
WHERE item_rank <= 3
ORDER BY category, item_rank;
--Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe? 
SELECT 
    CASE 
        WHEN "previous_purchases" > 5 THEN 'Repeat Buyer (>5 purchases)'
        ELSE 'Non-Repeat Buyer (<=5 purchases)'
    END AS buyer_type,
    COUNT(*) AS total_customers,
    COUNT(CASE WHEN "subscription_status" = 'Yes' THEN 1 END) AS subscribers,
    ROUND(
        (COUNT(CASE WHEN "subscription_status" = 'Yes' THEN 1 END)::numeric / COUNT(*)) * 100, 
        2
    ) AS subscription_rate_percentage
FROM customer
GROUP BY buyer_type;
--Q10. What is the revenue contribution of each age group?
select age_group,
SUM("purchase_amount_(usd)") as total_revenue
from customer
group by age_group
order by total_revenue desc;
       
